namespace BAG {

//! This structure contains simple layer attribute information.
struct AttributeInfo
{
    AttributeInfo(const char* inMinName, const char* inMaxName,
        const char* inPath, const ::H5::PredType& inH5type)
        : minName(inMinName)
        , maxName(inMaxName)
        , path(inPath)
        , h5type(inH5type)
    {}

    //! The minimum value attribute name.
    const char* minName = nullptr;
    //! The maximum value attribute name.
    const char* maxName = nullptr;
    //! The HDF5 path to the attribute.
    const char* path = nullptr;
    //! The HDF5 type the attribute is.
    const ::H5::PredType& h5type;
};

//! Retrieve the simple layer attribute information.
AttributeInfo getAttributeInfo(LayerType layerType);

}  // namespace BAG

enum BAG_OPEN_MODE
{
    BAG_OPEN_READONLY   = 1,  //!< Open the BAG read only.  It cannot be written to.
    BAG_OPEN_READ_WRITE = 2,  //!< Open the BAG for reading and writing.
};

enum GEOREF_METADATA_PROFILE {
    UNKNOWN_METADATA_PROFILE = 0,
    NOAA_OCS_2022_10_METADATA_PROFILE
};

enum BAG_GROUP_TYPE
{
    NODE = 0,  //!< The NODE group type.
    ELEVATION,  //!< The ELEVATION group type.
    UNKNOWN_GROUP_TYPE,  //!< Unknown group type.
};

struct BagTrackingItem
{
    //! The row of the node of the BAG that was modified.
    uint32_t row;
    //! The column of the node of the BAG that was modified.
    uint32_t col;
    //! The original depth before this change.
    float depth;
    //! The original uncertainty before this change.
    float uncertainty;
    //! The reason code indicating why the modification was made.
    uint8_t track_code;
    //! The index number indicating the item in the metadata that describes the modifications.
    uint16_t list_series;
};

struct BagVRTrackingItem
{
    //! The row of the node of the BAG that was modified.
    uint32_t row;
    //! The column of the node of the BAG that was modified.
    uint32_t col;
    //! The row within the refined grid that was modified.
    uint32_t sub_row;
    //! The column within the refined grid that was modified.
    uint32_t sub_col;
    //! The original depth before this change.
    float depth;
    //! The original uncertainty before this change.
    float uncertainty;
    //! The reason code indicating why the modification was made.
    uint8_t track_code;
    //! The index number indicating the item in the metadata that describes the modifications.
    uint16_t list_series;
};

struct BagVRMetadataItem
{
    //! The index.
    uint32_t index;
    //! Number of nodes in easting
    uint32_t dimensions_x;
    //! Number of nodes in northing
    uint32_t dimensions_y;
    //! Node spacing in easting
    float resolution_x;
    //! Node spacing in northing
    float resolution_y;
    //! Offset east from SW corner of surrounding low-res cell to SW-most node
    float sw_corner_x;
    //! Offset north from SW corner of surrounding low-res cell to SW-most node
    float sw_corner_y;
};

struct BagVRRefinementsItem
{
    //! The depth.
    float depth;
    //! The uncertainty.
    float depth_uncrt;
};

struct BagVRNodeItem
{
    //! Hypotheses strength.
    float hyp_strength;
    //! Number of hypotheses.
    uint32_t num_hypotheses;
    //! Number of samples.
    uint32_t n_samples;
};

enum BAG_SURFACE_CORRECTION_TOPOGRAPHY {
    BAG_SURFACE_UNKNOWN = 0,        //!< Unknown
    BAG_SURFACE_GRID_EXTENTS,       //!< Optional corrector dataset grid coordinates, spanning the required BAG surface extents
    BAG_SURFACE_IRREGULARLY_SPACED, //!< Irregularly spaced corrector values in optional corrector dataset
};

struct BagVerticalDatumCorrections
{
    //! The X correction.
    double x;
    //! The Y correction.
    double y;
    //! The correctors.
    float z[BAG_SURFACE_CORRECTOR_LIMIT];
};

struct BagVerticalDatumCorrectionsGridded
{
    //! The correctors.
    float z[BAG_SURFACE_CORRECTOR_LIMIT];
};

struct BagVerticalCorrectorDef
{
    double nodeSpacingX; //! node spacing in x dimension in units defined by coord system
    double nodeSpacingY; //! node spacing in y dimension in units defined by coord system
    double swCornerX;    //! X coordinate of SW corner of vertical corrector surface in BAG_COORDINATES
    double swCornerY;    //! Y coordinate of SW corner of vertical corrector surface in BAG_COORDINATES
};

struct FieldDefinition
{
    //! The name of the definition.
    const char* name;
    //! The type of the definition; represents a DataType.
    uint8_t type;
};

typedef union {
    float f;
    uint32_t ui32;
    bool b;
    char* c;
} BAG_COMPOUND_DATA_PAYLOAD;

struct BagCompoundDataType
{
    BAG_DATA_TYPE type;
    BAG_COMPOUND_DATA_PAYLOAD data;
};

namespace BAG {

class CompoundDataType final {
public:
    CompoundDataType()
    {}
    explicit CompoundDataType(float value) noexcept
        : type(DT_FLOAT32)
        , m_data(value)
    {
    }
    explicit CompoundDataType(uint32_t value) noexcept
        : type(DT_UINT32)
        , m_data(value)
    {
    }
    explicit CompoundDataType(bool value) noexcept
        : type(DT_BOOLEAN)
        , m_data(value)
    {
    }
    explicit CompoundDataType(std::string value) noexcept
        : type(DT_STRING)
        , m_data(std::move(value))
    {
    }
    CompoundDataType(const CompoundDataType& other)
        : type(other.type)
    {
        switch (type)
        {
        case DT_FLOAT32:
            m_data.m_f = other.m_data.m_f;
            break;
        case DT_UINT32:
            m_data.m_ui32 = other.m_data.m_ui32;
            break;
        case DT_BOOLEAN:
            m_data.m_b = other.m_data.m_b;
            break;
        case DT_STRING:
            new(&m_data.m_s) std::string{other.m_data.m_s};
            break;
        default:
            throw InvalidType{};
        }
    }
    CompoundDataType(CompoundDataType&& other)
    {
        switch (type)
        {
        case DT_FLOAT32:
            m_data.m_f = other.m_data.m_f;
            break;
        case DT_UINT32:
            m_data.m_ui32 = other.m_data.m_ui32;
            break;
        case DT_BOOLEAN:
            m_data.m_b = other.m_data.m_b;
            break;
        case DT_STRING:
            new(&m_data.m_s) std::string{std::move(other.m_data.m_s)};
            break;
        default:
            throw InvalidType{};
        }
    }
    ~CompoundDataType() noexcept
    {
        if (type == DT_STRING)
            m_data.m_s.~basic_string<char>();
    }

    CompoundDataType& operator=(const CompoundDataType& rhs)
    {
        if (this == &rhs)
            return *this;

        if (type == DT_STRING)
        {
            if (rhs.type == DT_STRING)
                m_data.m_s = rhs.m_data.m_s;
            else
                m_data.m_s.~basic_string<char>();
        }

        switch (rhs.type)
        {
        case DT_FLOAT32:
            m_data.m_f = rhs.m_data.m_f;
            break;
        case DT_UINT32:
            m_data.m_ui32 = rhs.m_data.m_ui32;
            break;
        case DT_BOOLEAN:
            m_data.m_b = rhs.m_data.m_b;
            break;
        case DT_STRING:
            new(&m_data.m_s) std::string{rhs.m_data.m_s};
            break;
        default:
            throw InvalidType{};
        }

        type = rhs.type;

        return *this;
    }
    CompoundDataType& operator=(CompoundDataType&& rhs)
    {
        if (type == DT_STRING)
        {
            if (rhs.type == DT_STRING)
                m_data.m_s = std::move(rhs.m_data.m_s);
            else
                m_data.m_s.~basic_string<char>();
        }

        switch (rhs.type)
        {
        case DT_FLOAT32:
            m_data.m_f = rhs.m_data.m_f;
            break;
        case DT_UINT32:
            m_data.m_ui32 = rhs.m_data.m_ui32;
            break;
        case DT_BOOLEAN:
            m_data.m_b = rhs.m_data.m_b;
            break;
        case DT_STRING:
            new(&m_data.m_s) std::string{rhs.m_data.m_s};
            break;
        default:
            throw InvalidType{};
        }

        type = rhs.type;

        return *this;
    }
    CompoundDataType& operator=(float rhs) noexcept
    {
        if (type == DT_STRING)
            m_data.m_s.~basic_string<char>();

        type = DT_FLOAT32;
        m_data.m_f = rhs;

        return *this;
    }
    CompoundDataType& operator=(uint32_t rhs) noexcept
    {
        if (type == DT_STRING)
            m_data.m_s.~basic_string<char>();

        type = DT_UINT32;
        m_data.m_ui32 = rhs;

        return *this;
    }
    CompoundDataType& operator=(bool rhs) noexcept
    {
        if (type == DT_STRING)
            m_data.m_s.~basic_string<char>();

        type = DT_BOOLEAN;
        m_data.m_b = rhs;

        return *this;
    }
    CompoundDataType& operator=(std::string rhs) noexcept
    {
        if (type == DT_STRING)
            m_data.m_s = rhs;
        else
        {
            type = DT_STRING;
            new(&m_data.m_s) std::string{std::move(rhs)};
        }

        return *this;
    }

    bool operator==(const CompoundDataType& rhs) const noexcept
    {
        if (this->type != rhs.type)
            return false;

        switch (this->type)
        {
        case DT_FLOAT32:
            return m_data.m_f == rhs.m_data.m_f;
        case DT_UINT32:
            return m_data.m_ui32 == rhs.m_data.m_ui32;
        case DT_BOOLEAN:
            return m_data.m_b == rhs.m_data.m_b;
        case DT_STRING:
            return m_data.m_s == rhs.m_data.m_s;
        default:
            return false;
        }
    }

    bool operator!=(const CompoundDataType &rhs) const noexcept {
        return !(rhs == *this);
    }

    float asFloat() const
    {
        if (type != DT_FLOAT32)
            throw InvalidType{};

        return m_data.m_f;
    }
    uint32_t asUInt32() const
    {
        if (type != DT_UINT32)
            throw InvalidType{};

        return m_data.m_ui32;
    }
    bool asBool() const
    {
        if (type != DT_BOOLEAN)
            throw InvalidType{};

        return m_data.m_b;
    }
    const std::string& asString() const &
    {
        if (type != DT_STRING)
            throw InvalidType{};

        return m_data.m_s;
    }
    std::string& asString() &
    {
        if (type != DT_STRING)
            throw InvalidType{};

        return m_data.m_s;
    }

    DataType getType() const noexcept
    {
        return type;
    }

private:
    DataType type = DT_UNKNOWN_DATA_TYPE;
    union Data {
        Data(): m_b(false) {}
        Data(float f): m_f(f) {}
        Data(uint32_t ui32): m_ui32(ui32) {}
        Data(bool b): m_b(b) {}
        Data(std::string s): m_s(s) {}
        ~Data() {}

        float m_f;
        uint32_t m_ui32;
        bool m_b;
        std::string m_s;
    } m_data;
};

}

namespace BAG { namespace detail {

template <typename T>
struct GetFromCompoundDataType;

template<>
struct GetFromCompoundDataType<float> {
    static float get(const CompoundDataType& v) { return v.asFloat(); }
};

} }

namespace BAG { namespace detail {

template<>
struct GetFromCompoundDataType<uint32_t> {
    static uint32_t get(const CompoundDataType& v) { return v.asUInt32(); }
};

} }

namespace BAG { namespace detail {

template<>
struct GetFromCompoundDataType<bool> {
    static bool get(const CompoundDataType& v) { return v.asBool(); }
};

} }

namespace BAG { namespace detail {

template<>
struct GetFromCompoundDataType<std::string> {
    static const std::string& get(const CompoundDataType& v) { return v.asString(); }
};

} }

